<template>
  <div class="claim-work-table">
    <div class="table-options"><span>Sort any column to organize all results.</span><details class="column-picker"><summary>Select columns</summary><fieldset><legend class="sr-only">Visible claim columns</legend><label v-for="column in availableColumns" :key="column.id"><input v-model="selectedColumns" type="checkbox" :value="column.id" :disabled="selectedColumns.length === 1 && selectedColumns.includes(column.id)" /> {{ column.label }}</label><button type="button" @click="selectedColumns = defaultColumns">Restore defaults</button></fieldset></details></div>
    <div class="table-scroll" tabindex="0" aria-label="Claim work items"><table><thead><tr><th v-for="column in visibleColumns" :key="column.id" :aria-sort="sortBy === column.id ? (direction === 'asc' ? 'ascending' : 'descending') : 'none'"><button type="button" class="sort-button" @click="emit('sort', column.id)">{{ column.label }}<span aria-hidden="true">{{ sortBy === column.id ? direction === 'asc' ? ' ↑' : ' ↓' : ' ↕' }}</span></button></th><th>Next action</th></tr></thead><tbody><tr v-for="item in items" :key="workItemKey(item)" :data-stage="workStage(item)"><td v-for="column in visibleColumns" :key="column.id">
      <template v-if="column.id === 'organization'">{{ organization(item)?.name || item.organization_name || 'Organization' }}</template>
      <template v-else-if="column.id === 'date_of_service'">{{ billingDate(item.date_of_service) }}</template>
      <template v-else-if="column.id === 'client_name'"><a :href="clientLink(item)" class="patient-link">{{ item.client_name || `Client #${item.client_id}` }}</a><button class="record-link" type="button" @click="emit('open', item)">{{ workItemTitle(item) }}</button></template>
      <template v-else-if="['provider_name', 'billing_provider_name', 'supervisor_name'].includes(column.id)"><a v-if="providerId(item, column.id) && organization(item)?.slug" :href="providerLink(item, column.id)">{{ providerName(item, column.id) || `Provider #${providerId(item, column.id)}` }}</a><span v-else>{{ providerName(item, column.id) || '—' }}</span></template>
      <template v-else-if="column.id === 'amount_cents'">{{ item.amount_cents == null ? 'Not set' : money(item.amount_cents, item.currency_code) }}</template>
      <template v-else-if="column.id === 'diagnosis_codes'">{{ diagnosisList(item.diagnosis_codes) || 'Not recorded' }}</template>
      <template v-else-if="column.id === 'stage'"><span class="badge" :class="claimStatusTone(workStage(item))">{{ claimStatusLabel(workStage(item)) }}</span><small v-if="item.service_change_pending">Service correction pending</small></template>
      <template v-else-if="column.id === 'submission_type'">{{ workClaimId(item) ? submissionTypeLabel(item) : 'Not submitted' }}</template>
      <template v-else>{{ item[column.id] ?? '—' }}</template>
    </td><td><button type="button" class="record-link action" @click="emit('open', item)">{{ workStage(item) === 'ready_to_submit' ? 'Review claim' : ['note_needed','draft','pending_review','revisions_needed'].includes(workStage(item)) ? 'View progress' : 'View claim' }} →</button></td></tr></tbody></table></div>
  </div>
</template>
<script setup>
import { computed, ref, watch } from 'vue';
import { billingDate, diagnosisList, claimStatusLabel, claimStatusTone, workStage, workClaimId, workItemKey, workItemTitle, submissionTypeLabel } from '../../utils/billingWorkspace.js';
const props = defineProps({ items: { type: Array, default: () => [] }, organizations: { type: Array, default: () => [] }, multipleOrganizations: Boolean, sortBy: { type: String, default: 'date_of_service' }, direction: { type: String, default: 'desc' }, preferenceKey: { type: String, default: '' } });
const emit = defineEmits(['open','sort']);
const columns = [ ['organization','Organization'], ['date_of_service','Date of service'], ['client_name','Patient'], ['service_code','Service'], ['provider_name','Clinician'], ['billing_provider_name','Billed as provider'], ['supervisor_name','Supervisor / billed as'], ['amount_cents','Charge'], ['place_of_service','Place of service'], ['diagnosis_codes','Diagnoses'], ['units','Units'], ['stage','Stage'], ['payer_name','Payer'], ['submission_type','Submission type'] ].map(([id,label]) => ({ id,label }));
const defaultColumns = ['organization','date_of_service','client_name','service_code','provider_name','supervisor_name','amount_cents','stage'];
const selectedColumns = ref([...defaultColumns]);
try { const saved = JSON.parse(localStorage.getItem(props.preferenceKey) || 'null'); if (Array.isArray(saved) && saved.some(id => columns.some(column => column.id === id))) selectedColumns.value = saved.filter(id => columns.some(column => column.id === id)); } catch { /* Optional display preference. */ }
watch(selectedColumns, value => { if (props.preferenceKey) try { localStorage.setItem(props.preferenceKey, JSON.stringify(value)); } catch { /* Optional display preference. */ } }, { deep: true });
const availableColumns = computed(() => columns.filter(column => column.id !== 'organization' || props.multipleOrganizations));
const visibleColumns = computed(() => availableColumns.value.filter(column => selectedColumns.value.includes(column.id)));
const organization = item => props.organizations.find(org => Number(org.id) === Number(item.agency_id));
const prefix = item => organization(item)?.slug ? `/${encodeURIComponent(organization(item).slug)}` : '';
const clientLink = item => `${prefix(item)}/admin/clients/${Number(item.client_id)}?tab=billing&agencyId=${Number(item.agency_id)}`;
const providerId = (item, field) => field === 'supervisor_name' ? item.supervisor_user_id || item.billing_provider_user_id || item.provider_user_id : item[field.replace('_name','_user_id')];
const providerName = (item, field) => field === 'supervisor_name' ? item.supervisor_name || item.billing_provider_name || item.provider_name : item[field];
const providerLink = (item, field) => `${prefix(item)}/admin/users/${Number(providerId(item,field))}`;
const money = (cents, currency = 'USD') => { try { return new Intl.NumberFormat('en-US',{style:'currency',currency:currency || 'USD'}).format(Number(cents)/100); } catch { return '—'; } };
</script>
<style scoped>
.table-options{display:flex;align-items:center;justify-content:space-between;gap:12px;margin:12px 0;color:var(--app-muted,#63718a);font-size:12px}.column-picker{position:relative;color:var(--app-ink,#17324d)}.column-picker summary{cursor:pointer;padding:9px 12px;border:1px solid #cbd8e5;border-radius:7px;white-space:nowrap}.column-picker fieldset{position:absolute;right:0;z-index:10;display:grid;gap:9px;background:var(--bg-card,#fff);border:1px solid #cbd8e5;border-radius:9px;box-shadow:0 8px 25px #17263d26;padding:16px;min-width:220px}.column-picker label{display:flex;gap:9px;align-items:center}.table-scroll{overflow:auto;max-width:100%}table{width:100%;border-collapse:collapse;text-align:left;font-size:13px}th,td{padding:12px 10px;border-bottom:1px solid var(--app-line,#e5ecf5);vertical-align:top;min-width:95px}th{background:var(--app-surface-muted,#f4f7fb);font-size:11px;white-space:nowrap}td:has(.patient-link){min-width:170px}a,.record-link{color:var(--app-text-blue,#1555b0)}.patient-link{font-weight:650}.record-link,.sort-button{border:0;background:none;font:inherit;cursor:pointer;padding:0;text-align:left}.record-link{display:block;margin-top:5px}.sort-button{color:inherit;white-space:nowrap}.action{white-space:nowrap}small{display:block;margin-top:5px;color:var(--app-muted,#63718a)}.badge{display:inline-block;border-radius:14px;padding:5px 8px;background:#eef4ff;color:#285caa;font-size:11px;white-space:nowrap}.badge.warning{background:#fff6df;color:#745318}.badge.danger{background:#ffeded;color:#9b2733}.badge.success{background:#e9f7ef;color:#1b6544}button:focus-visible,summary:focus-visible,a:focus-visible{outline:3px solid #1555b0;outline-offset:3px}.sr-only{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0,0,0,0)}@media(max-width:600px){.table-options>span{display:none}.table-options{justify-content:flex-end}.column-picker fieldset{max-height:60vh;overflow:auto}}
</style>
